import math

# Symbolic constants to replace magic numbers
DILIMITER_EVEN_DIVISOR = 2
MINIMUM_FRACTIONAL_NEEDED = 1
ZERO_VALUE = 0
ONE_VALUE = 1
NUMBER_OF_DEVIATIONS = 1

class Statistics3:
    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % DILIMITER_EVEN_DIVISOR == DILIMITER_EVEN_DIVISOR - ZERO_VALUE:
            return sorted_data[n // DILIMITER_EVEN_DIVISOR]
        else:
            return (sorted_data[n // DILIMITER_EVEN_DIVISOR - ONE_VALUE] + sorted_data[n // DILIMITER_EVEN_DIVISOR]) / DILIMITER_EVEN_DIVISOR

    @staticmethod
    def mode(data):
        counts = Statistics3._count_values(data)
        max_count = max(counts.values())
        mode_values = [value for value, count in counts.items() if count == max_count]
        return mode_values

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)
        numerator = Statistics3._covariance_sum(x, y, mean_x, mean_y)
        variance_x = Statistics3._variance_sum(x, mean_x)
        variance_y = Statistics3._variance_sum(y, mean_y)
        denominator = math.sqrt(variance_x * variance_y)
        if denominator == ZERO_VALUE:
            return None
        return numerator / denominator

    @staticmethod
    def mean(data):
        if len(data) == ZERO_VALUE:
            return None
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data):
        matrix = []
        for i in range(len(data[0])):
            row = []
            for j in range(len(data[0])):
                column1 = Statistics3._extract_column(data, i)
                column2 = Statistics3._extract_column(data, j)
                correlation = Statistics3.correlation(column1, column2)
                row.append(correlation)
            matrix.append(row)
        return matrix

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        if n < DILIMITER_EVEN_DIVISOR:
            return None
        mean_value = Statistics3.mean(data)
        variance = Statistics3._variance_sum(data, mean_value) / (n - NUMBER_OF_DEVIATIONS)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        mean = Statistics3.mean(data)
        std_deviation = Statistics3.standard_deviation(data)
        if std_deviation is None or std_deviation == ZERO_VALUE:
            return None
        return Statistics3._compute_z_scores(data, mean, std_deviation)

    @staticmethod
    def _count_values(data):
        counts = {}
        for value in data:
            counts[value] = counts.get(value, ZERO_VALUE) + ONE_VALUE
        return counts

    @staticmethod
    def _covariance_sum(x, y, mean_x, mean_y):
        return sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))

    @staticmethod
    def _variance_sum(data, mean):
        return sum((x - mean) ** DILIMITER_EVEN_DIVISOR for x in data)

    @staticmethod
    def _extract_column(data, index):
        return [row[index] for row in data]

    @staticmethod
    def _compute_z_scores(data, mean, std_deviation):
        return [(x - mean) / std_deviation for x in data]
